function bfs(graph, start, end) {
  const visited = new Set([start]);
  const queue = [start];
  let dist = 0;
  while (queue.length) {
    const n = queue.shift();
    if (n === end) return dist;
    for (const nb of graph[n] || []) {
      if (!visited.has(nb)) {
        visited.add(nb);
        queue.push(nb);
      }
    }
    dist++;
  }
  return -1;
}
module.exports = { bfs };

