class Account {
  constructor(balance) { this._b = balance; }
  async balance() { await new Promise((r) => setImmediate(r)); return this._b; }
  async setBalance(b) { await new Promise((r) => setImmediate(r)); this._b = b; }
}
async function transfer(from, to, amount) {
  const a = await from.balance();
  const b = await to.balance();
  if (a < amount) throw new Error('insufficient');
  await from.setBalance(a - amount);
  await to.setBalance(b + amount);
}
module.exports = { Account, transfer };

